fn is_ascii_digit(c: char) -> bool {
    c >= '0' && c <= '9'
}

fn all_digits(s: String) -> bool {
    for c in s.chars() {
        if !is_ascii_digit(c) {
            return false;
        }
    }
    true
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_is_ascii_digit() {
        assert!(is_ascii_digit('0'));
        assert!(is_ascii_digit('5'));
        assert!(is_ascii_digit('9'));
        assert!(!is_ascii_digit('a'));
        assert!(!is_ascii_digit(' '));
        assert!(!is_ascii_digit('߉')); // some non-ASCII digit
    }

    #[test]
    fn test_all_digits() {
        assert!(all_digits("".to_string()));
        assert!(all_digits("0123456789".to_string()));
        assert!(all_digits("123456".to_string()));
        assert!(!all_digits("12a34".to_string()));
        assert!(!all_digits("１２３".to_string())); // fullwidth digits
        assert!(!all_digits("123 456".to_string()));
    }
}